RDR.challenges=[{"id":"bandit","n":"Bandit","unlock":"Hold up anyone in a town (aim at them and press the hold-up prompt).","ranks":[{"t":"Hold up five townsfolk.","how":"Valentine works well: pull your bandana up, aim at a lone pedestrian and choose “Hold up”. Ride off after each one so the law doesn’t pile up.","pts":[[-71.98,145.29,"Valentine"]]},{"t":"Rob two coaches along the road, or complete any two coach-robbery missions.","how":"Gang members (Sean, Bill, Charles) offer coach-robbery tips in camp; each one finished counts. Or block a passing stagecoach, hold up the driver and loot the lockbox on the roof."},{"t":"Rob the cash register in any four shops in one day.","how":"Start when shops open (around 7am), mask up and follow the numbers: three Valentine shops in a row, then ride west over the Dakota River into West Elizabeth for the fourth, so the New Hanover law can’t follow you. Don’t save or reload mid-way: the count resets. Backup if Valentine gets too hot: Rhodes general store + gunsmith.","route":1,"pts":[[-68.65,142.43,"1. Valentine General Store"],[-68.65,143.18,"2. Valentine Doctor"],[-69.17,143.31,"3. Valentine Gunsmith"],[-93.53,111.93,"4. Strawberry General Store"]]},{"t":"Rob three coaches in a day.","how":"Wait on the busy Saint Denis–Rhodes road or the Valentine–Strawberry road; coaches pass every few in-game minutes. Rob, hide your horse off-road, then wait for the next.","pts":[[-112.38,175.08,"Rhodes road"],[-116.05,204.62,"Saint Denis road"]]},{"t":"Amass a $250 bounty in one state.","how":"Pick one state (New Hanover is easiest) and keep committing crimes there: robbing Valentine shops and fighting the posse adds up fast. Pay it off at any post office afterwards."},{"t":"Steal five horses and sell them to the horse fence at Clemens Cove.","how":"The horse fence opens after “Horse Flesh for Dinner” (Chapter 3). Steal horses tied up in Rhodes, ride them to the fence one by one and sell them.","q":["horse-flesh-for-dinner"],"route":1,"pts":[[-112.38,175.08,"1. Steal a horse in Rhodes"],[-111.52,165.46,"2. Clemens Cove horse fence"]]},{"t":"Rob $50 of cash and valuables from townsfolk and travellers.","how":"Hold people up and loot them, or rob camps of hostile gangs on the roads. Valuables only count once sold to a fence."},{"t":"Steal seven wagons and sell them to the fence at Emerald Ranch.","how":"Wagons parked around Emerald Ranch and Emerald Station are right next to the fence: take one, drive it into the fence’s barn and sell it.","route":1,"pts":[[-76.29,180.67,"1. Steal a wagon around Emerald Ranch"],[-79.72,178.64,"2. Emerald Ranch fence"]]},{"t":"Hogtie someone and leave them on the railroad three times.","how":"Lasso a lone traveller near Emerald Station, hogtie them, carry them to the tracks and wait for a train. Quiet stretches of track keep witnesses away.","pts":[[-76.29,180.67,"Emerald Station tracks"]]},{"t":"Complete five train robberies without dying or being caught.","how":"Jump on a train from horseback, or block the line with a wagon, hold up the passengers and loot the safe. Ride far away before the law arrives."}]},{"id":"explorer","n":"Explorer","unlock":"Pick up your first treasure map: buy the Jack Hall Gang map from Máximo near Flatneck Station ($10, or $5 if you haggle) from Chapter 2.","ranks":[{"t":"Find a treasure map.","how":"Buy the Jack Hall Gang map from Máximo at Flatneck Station.","pts":[[-93.133,135.158,"Máximo"]],"q":["ch2"]},{"t":"Find a treasure (Jack Hall Gang map 2).","how":"Caliban’s Seat, south of Valentine: climb up, keep to the right-hand rock wall and drop into the crack at the bottom.","pts":[[-79.318,141.184,"Caliban’s Seat"]]},{"t":"Find a treasure (Jack Hall Gang map 3).","how":"Cotorra Springs, above Fort Wallace: the central rock pillar between the second “o” and the “r” of Cotorra.","pts":[[-47.114,151.875,"Cotorra Springs"]]},{"t":"Find a treasure (Jack Hall Gang gold).","how":"Swim to the central island of O’Creagh’s Run; the rock beside the mossy patch on the north side.","pts":[[-54.256,182.864,"O’Creagh’s Run"]]},{"t":"Find a treasure (High Stakes map 2).","how":"Kill or loot the treasure hunter (Explorer map 1) for the High Stakes map, then search behind Cumberland Falls.","pts":[[-93.305,125.837,"Treasure hunter"],[-76.096,128.195,"Cumberland Falls"]],"route":1},{"t":"Find a treasure (High Stakes map 3).","how":"Barrow Lagoon.","pts":[[-51.408,129.397,"Barrow Lagoon"]]},{"t":"Find a treasure (High Stakes gold).","how":"Near Fort Wallace.","pts":[[-51.753,157.851,"Near Fort Wallace"]]},{"t":"Find a treasure (Poisonous Trail map 2).","how":"Get the Poisonous Trail map from the cabin at Cairn Lodge (deal with the gang there), then the hollow tree at Face Rock.","pts":[[-40.129,129.49,"Cairn Lodge"],[-99.281,171.8,"Face Rock"]],"route":1},{"t":"Find a treasure (Poisonous Trail map 3).","how":"Serpent Mound.","pts":[[-76.056,205.196,"Serpent Mound"]]},{"t":"Find a treasure (Poisonous Trail gold).","how":"The cave at Elysian Pool.","pts":[[-64.37,198.186,"Elysian Pool"]]}]},{"id":"gambler","n":"Gambler","unlock":"Win a hand of poker (Valentine saloon, from Chapter 2).","ranks":[{"t":"Win five hands of Poker.","how":"Smithfield’s Saloon in Valentine. Fold weak hands early; you only need hand wins, not a whole game.","pts":[[-68.57,142.64,"Valentine saloon"]]},{"t":"In Blackjack, double down and win the hand five times.","how":"Only double down on 10 or 11 against a dealer showing 2–6. Blackjack is in Rhodes and Van Horn (and Blackwater in the Epilogue).","pts":[[-114.12,177.0,"Rhodes saloon"],[-74.38,210.47,"Van Horn saloon"]]},{"t":"Win three games of Five Finger Fillet.","how":"Press the button exactly as the knife lands on each gap; slow and steady beats fast.","pts":[[-68.57,142.64,"Valentine"],[-74.38,210.47,"Van Horn"]]},{"t":"Bust one poker table out in each location: Flatneck Station, Saint Denis, Valentine.","how":"Each table must lose all its players to you. Play tight and go all-in only with strong hands.","route":1,"pts":[[-92.79,142.06,"1. Flatneck Station"],[-68.57,142.64,"2. Valentine"],[-110.94,204.05,"3. Saint Denis"]]},{"t":"Win three rounds of Dominoes without drawing tiles against two or fewer opponents.","how":"Dominoes is played in camp and at Saint Denis/Lagras. Play one opponent and lead with your doubles."},{"t":"Beat the blackjack dealer in two locations: Rhodes and Van Horn Trading Post.","how":"Win at least one hand at each.","route":1,"pts":[[-114.12,177.0,"1. Rhodes"],[-74.38,210.47,"2. Van Horn"]]},{"t":"Beat the Five Finger Fillet opponent in each location: Strawberry, Valentine, Van Horn Trading Post.","how":"Strawberry first, then east along the road through Valentine to Van Horn.","route":1,"pts":[[-94.07,113.02,"1. Strawberry"],[-68.57,142.64,"2. Valentine"],[-74.38,210.47,"3. Van Horn"]]},{"t":"Win three hands of Blackjack with three or more hits.","how":"Hit on low totals (under 12) to rack up hits safely; small cards are common in a fresh shoe."},{"t":"Win three games of Dominoes in a row.","how":"Pick the “All Fives” variant against one opponent."},{"t":"Win three hands of Poker in a row.","how":"Bet small to keep weak players in, and fold anything marginal; folding doesn’t break the streak, losing a hand at showdown does.","pts":[[-68.57,142.64,"Valentine"],[-110.94,204.05,"Saint Denis"]]}]},{"id":"herbalist","n":"Herbalist","unlock":"Pick a Yarrow plant.","ranks":[{"t":"Pick six Yarrow plants.","how":"White flat-topped flowers, common in the Heartlands around Valentine. Look along the roads.","pts":[[-71.98,145.29,"Around Valentine"]]},{"t":"Pick and eat four species of berry.","how":"Blackberry, Red Raspberry, Wintergreen Berry and Evergreen Huckleberry all count. Wintergreen and huckleberries grow in the forests north of Valentine."},{"t":"Craft seven items using Sage as an ingredient.","how":"Use Desert or Red Sage at a campfire to season meat or make tonics."},{"t":"Pick five mushrooms and feed them to your horse.","how":"Parasol, Chanterelle and Oyster mushrooms grow in Lemoyne and Roanoke forests. Feed from the horse’s inventory."},{"t":"Craft nine items using Indian Tobacco as an ingredient.","how":"Indian Tobacco grows on the Heartlands plains; craft Potent Bitters/Tonics or season meat."},{"t":"Pick 15 different species of herb.","how":"Ride through several biomes: Heartlands, Lemoyne bayou, Big Valley."},{"t":"Craft and use five Special Miracle Tonics.","how":"Needs Ginseng (American or Alaskan) and Bay Bolete plus a Miracle Tonic."},{"t":"Use Oleander Sage to craft six poison weapons.","how":"Oleander Sage grows in the Lemoyne bayou; craft poison arrows or poison throwing knives (see Crafting Pamphlets)."},{"t":"Pick one of each species of herb.","how":"Includes rare ones: Alaskan Ginseng (Ambarino), Desert Sage (New Austin, Epilogue), Creeping Thyme, Vanilla Flower and others."},{"t":"Season and cook all 11 types of meat.","how":"Season each kind of meat at a campfire with an herb."}]},{"id":"horseman","n":"Horseman","unlock":"Kill a rabbit from horseback.","ranks":[{"t":"Kill five rabbits from horseback.","how":"Rabbits are everywhere in the Heartlands; use a varmint rifle or bow at a slow canter.","wild":["animal_rabbit"]},{"t":"Jump over three obstacles in 15 seconds.","how":"Fences along the Heartlands ranches line up nicely; build speed and press jump just before each."},{"t":"Ride from Valentine to Rhodes in less than five minutes.","how":"Follow the road south-east through Emerald Ranch with a fast horse and full stamina cores; the timer starts as you leave Valentine.","route":1,"pts":[[-71.98,145.29,"Start: Valentine"],[-76.29,180.67,"Emerald Ranch"],[-112.38,175.08,"Finish: Rhodes"]]},{"t":"While mounted, drag a victim for 3,300 feet using your lasso.","how":"Lasso a hogtied enemy (or bounty) and ride in long straight lines along the road."},{"t":"Trample five animals while on horseback.","how":"Ride through flocks of chickens or birds at ranches; small animals count."},{"t":"Ride from Strawberry to Saint Denis in less than nine minutes without touching water.","how":"Cross the rivers by bridges only: Strawberry → Valentine → Emerald Ranch → Rhodes road → Saint Denis.","route":1,"pts":[[-94.07,113.02,"Start: Strawberry"],[-71.98,145.29,"Valentine"],[-76.29,180.67,"Emerald Ranch"],[-116.05,204.62,"Finish: Saint Denis"]]},{"t":"Kill seven enemies from horseback without dismounting.","how":"Ride at hostile gang camps or use a bounty mission; Dead Eye helps."},{"t":"Kill nine predators from horseback.","how":"Wolves, cougars, bears and alligators count. Switch on the wolf habitat: packs come to you.","wild":["animal_wolf_gray"]},{"t":"Ride from Van Horn to Blackwater in less than 17 minutes without touching water.","how":"Use bridges only: Van Horn → Emerald Ranch → Valentine → Strawberry road → Blackwater. Blackwater is only open in the Epilogue.","q":["ch7"],"route":1,"pts":[[-72.17,209.51,"Start: Van Horn"],[-76.29,180.67,"Emerald Ranch"],[-71.98,145.29,"Valentine"],[-111.45,133.68,"Finish: Blackwater"]]},{"t":"Break every wild horse breed.","how":"Switch on the Wild horses in the Wildlife tab to see where each breed roams.","wild":["animal_horse_wild_mustang","animal_horse_wild_nokota"]}]},{"id":"hunter","n":"Master Hunter","unlock":"Skin a deer.","ranks":[{"t":"Skin three deer.","how":"Deer graze in the Heartlands and Big Valley at dawn and dusk; varmint rifle or bow to the head.","wild":["animal_deer"]},{"t":"Collect three perfect-quality rabbit pelts.","how":"Use Small Game Arrows or the varmint rifle; check the stars with binoculars first.","wild":["animal_rabbit"]},{"t":"Track ten different species using your binoculars.","how":"Study an animal first, then hold the track button while aiming binoculars at it."},{"t":"Call an animal and get a clean kill five times.","how":"Use the animal call (hold the left d-pad / whistle) to make a deer or elk look at you, then a clean headshot."},{"t":"Skin three black or grizzly bears.","how":"Black bears roam Roanoke Ridge and the forests north of Valentine; grizzlies live in the Grizzlies. Use a rifle with Express ammo.","wild":["animal_bear_black","animal_bear"]},{"t":"Kill five cougars with your bow, then skin them.","how":"Cougars are rare: Big Valley and the Grizzlies cliffs. Use poison or improved arrows, and bait if you have it.","wild":["animal_cougar"]},{"t":"Use bait to lure and kill both a herbivore and a predator.","how":"Drop herbivore bait in the Heartlands for deer, predator bait in the woods for wolves or coyotes, then hide downwind."},{"t":"Catch three small fish without using a fishing rod.","how":"Shoot or arrow fish in shallow streams, or catch them by hand where they flop."},{"t":"Kill an opossum playing possum.","how":"Startle an opossum so it plays dead, then kill it. Common in the Lemoyne swamps.","wild":["animal_possum"]},{"t":"Find and kill the Legendary Giaguaro Panther.","how":"Only appears after reaching rank 9. East of Braithwaite Manor, by the water. Use Express ammo and a high-calibre rifle.","pts":[[-126.424,184.919,"Legendary Giaguaro Panther"]],"wild":["legendary_animal_panther"]}]},{"id":"sharpshooter","n":"Sharpshooter","unlock":"Kill a flying bird.","ranks":[{"t":"Kill three flying birds.","how":"Shotgun or varmint rifle; ducks over the lakes near Valentine.","wild":["animal_duck_mallard"]},{"t":"Kill two different animal species in the same Dead Eye use.","how":"Find mixed herds (deer with birds nearby), activate Dead Eye, paint both."},{"t":"Kill five flying birds while on a moving train.","how":"Ride a train through the Heartlands or Bayou; shoot birds from the platform at the back."},{"t":"Kill an enemy at least 80 feet away with a thrown tomahawk.","how":"Throw upward to give it an arc; Homing Tomahawks help (Crafting Pamphlets)."},{"t":"Kill six animals without switching or reloading your weapon.","how":"Use a weapon with a big magazine (Litchfield repeater) on a herd or a flock."},{"t":"Kill someone at least 660 feet away with a long scoped rifle.","how":"Find a high spot overlooking a gang hideout; use the Rolling Block or Carcano rifle."},{"t":"Get seven headshots in a row.","how":"Use Dead Eye on human enemies; a miss resets the count."},{"t":"Disarm three enemies without reloading or switching your weapon.","how":"Shoot the weapon hand in Dead Eye; a revolver with 6 rounds is enough."},{"t":"Shoot three people’s hats off in the same Dead Eye use.","how":"Pick a group of townsfolk, paint each hat in Dead Eye. Better done after Dead Eye upgrades."},{"t":"Kill three flying birds with three consecutive long scoped shots.","how":"Big slow birds (vultures, eagles) over open plains; any miss resets the count.","wild":["animal_vulture_western"]}]},{"id":"survivalist","n":"Survivalist","unlock":"Catch a fish.","ranks":[{"t":"Catch three Bluegill.","how":"The lakes around Valentine and Flat Iron Lake, with bread or cheese bait.","wild":["fish_bluegill"]},{"t":"Hand in five animals to camp or a trapper.","how":"Donate carcasses to Pearson in camp, or sell to a trapper.","pts":[[-110.95,207.99,"Trapper: Saint Denis"],[-96.79,128.21,"Trapper: Riggs Station"],[-125.3,102.24,"Trapper: Tall Trees"],[-64.47,192.32,"Trapper: Emerald Ranch area"]]},{"t":"Kill five animals with a varmint rifle.","how":"Buy the Varmint Rifle at a gunsmith; rabbits and squirrels are easy targets."},{"t":"Craft a dynamite, fire, improved, poison and small-game arrow.","how":"Needs those five arrow pamphlets: see the Crafting Pamphlets category for where to get each."},{"t":"Catch a fish in the Bayou from a riverboat and while standing on train tracks.","how":"Fish from the Saint Denis riverboat deck, and from the rail bridge over the bayou."},{"t":"Kill a scavenging animal while it is feeding on a corpse five times.","how":"Leave carcasses out and come back: vultures and coyotes soon arrive."},{"t":"Kill eight small game animals with consecutive shots using small-game arrows.","how":"Small Game Arrow pamphlet first. A miss resets the count; target slow birds and rabbits."},{"t":"Craft a homing tomahawk, improved tomahawk, volatile dynamite and volatile fire bottle.","how":"All need pamphlets: see Crafting Pamphlets."},{"t":"Catch a fish weighing at least 19 lb.","how":"Large Muskie, Lake Sturgeon or Northern Pike from big lakes (Flat Iron Lake, Owanjila).","wild":["fish_lake_sturgeon","fish_muskie_clear"]},{"t":"Catch one of each type of fish.","how":"Use the Fish groups in the Wildlife tab to find each species; some live only in New Austin (Epilogue)."}]},{"id":"weapons","n":"Weapons Expert","unlock":"Kill three enemies with a knife.","ranks":[{"t":"Kill three enemies with a knife.","how":"Melee a hostile gang member or bounty target."},{"t":"Kill three enemies in 10 seconds using only throwing knives.","how":"Buy throwing knives at a gunsmith; hit quickly in Dead Eye."},{"t":"Kill three birds of prey using only a tomahawk.","how":"Hawks and eagles perch on fence posts and dead animals; throw from close.","wild":["animal_hawk_ferruginous","animal_eagle_golden"]},{"t":"Kill ten enemies with a shotgun using crafted ammo.","how":"Craft slugs or incendiary buckshot (Crafting Pamphlets), then raid a gang hideout."},{"t":"Kill five mounted enemies using one throwing knife per kill.","how":"Wait for riders on the road, or face a mounted posse."},{"t":"Kill four enemies at the same time with a single stick of dynamite.","how":"Hostile camps cluster around the fire: throw it into the middle."},{"t":"Kill four consecutive enemies by throwing and retrieving the same tomahawk.","how":"Throw, then pick it back up after each kill."},{"t":"Kill 15 enemies using a long-barrelled sidearm.","how":"Customise a revolver/pistol with a long barrel at a gunsmith."},{"t":"Kill nine unaware enemies from behind using the bow.","how":"Stealth into gang camps at night with the bow; no alert means it still counts."},{"t":"Kill a grizzly bear without taking damage, using only throwing knives.","how":"Use poison throwing knives and Dead Eye; hit from your horse and keep moving.","wild":["animal_bear"]}]}];
